import csv
import json
import math
from pathlib import Path
from json.encoder import encode_basestring, encode_basestring_ascii

ROOT = Path('/root')


class Currency(float):
    """Float marker serialized with exactly two decimal places."""


class FixedCurrencyEncoder(json.JSONEncoder):
    def iterencode(self, o, _one_shot=False):
        if self.check_circular:
            markers = {}
        else:
            markers = None
        if self.ensure_ascii:
            _encoder = encode_basestring_ascii
        else:
            _encoder = encode_basestring

        def floatstr(value, allow_nan=self.allow_nan,
                     _repr=float.__repr__, _inf=math.inf, _neginf=-math.inf):
            if isinstance(value, Currency):
                return format(value, '.2f')
            if value != value:
                text = 'NaN'
            elif value == _inf:
                text = 'Infinity'
            elif value == _neginf:
                text = '-Infinity'
            else:
                return _repr(value)
            if not allow_nan:
                raise ValueError(
                    'Out of range float values are not JSON compliant: ' + repr(value)
                )
            return text

        _iterencode = json.encoder._make_iterencode(
            markers, self.default, _encoder, self.indent, floatstr,
            self.key_separator, self.item_separator, self.sort_keys,
            self.skipkeys, _one_shot
        )
        return _iterencode(o, 0)


def load_json(name):
    with (ROOT / name).open() as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return Currency(round(value + 0.0000000001, 2))


def nonblank(value):
    return value is not None and str(value).strip() != ''


def main():
    manifest = load_json('panel_manifest.json')
    shipper_rows = load_csv('shipper_cost.csv')
    contract_rows = load_csv('contract_terms.csv')
    adjustment_rows = load_csv('network_adjustments.csv')
    override_rows = load_csv('lab_capacity_overrides.csv')
    holdouts = load_json('holdouts.json')
    template = load_json('report_template.json')

    excluded_codes = {
        row['panel_code']
        for row in holdouts.get('holdouts', [])
        if row.get('holdout_state') == 'exclude'
    }

    shipper_cost_by_class = {
        row['shipper_class']: float(row['shipper_cost_usd'])
        for row in shipper_rows
    }
    adjustment_by_tier = {
        row['network_tier']: float(row['network_adjustment_per_run_per_lab_usd'])
        for row in adjustment_rows
    }

    active_labs_override = {}
    for row in override_rows:
        if row.get('approval') != 'approved':
            continue
        if not nonblank(row.get('rev')) or not nonblank(row.get('active_labs')):
            continue
        rev = int(row['rev'])
        code = row['panel_code']
        if code not in active_labs_override or rev > active_labs_override[code]['rev']:
            active_labs_override[code] = {
                'rev': rev,
                'active_labs': int(row['active_labs']),
            }

    panels = []
    for cluster in manifest.get('service_clusters', []):
        for panel in cluster.get('panels', []):
            if panel.get('analysis_mode') != 'review':
                continue
            if panel.get('panel_code') in excluded_codes:
                continue
            panels.append(panel)

    panel_outputs = []
    for panel in panels:
        panel_refs = {panel['panel_name'], *panel.get('alias_labels', [])}
        matching_contracts = [
            row for row in contract_rows
            if row.get('status_flag') == 'current' and row.get('panel_ref') in panel_refs
        ]
        if not matching_contracts:
            raise ValueError(f"No current contract row found for {panel['panel_code']}")
        contract = max(matching_contracts, key=lambda row: row['effective_week'])
        base_payment = float(contract['base_payment_per_run_per_lab_usd'])

        network_adjustment = adjustment_by_tier.get(panel.get('network_tier'), 0.0)
        shipper_cost = shipper_cost_by_class[panel['shipper_class']]
        active_labs = active_labs_override.get(
            panel['panel_code'],
            {'active_labs': int(panel['default_active_labs'])},
        )['active_labs']
        total_payment = base_payment + network_adjustment

        annual_values = {}
        margins = {}
        for cadence, runs_per_year, test_key in [
            ('14_day', 26, 'tests_per_lab_per_run_14_day'),
            ('28_day', 13, 'tests_per_lab_per_run_28_day'),
        ]:
            tests_per_lab_per_run = float(panel[test_key])
            annual_revenue = total_payment * active_labs * runs_per_year
            annual_reagent_cost = (
                float(panel['reagent_cost_per_1000_tests_usd'])
                * active_labs
                * tests_per_lab_per_run
                * runs_per_year
                / 1000.0
            )
            annual_shipper_cost = shipper_cost * runs_per_year
            annual_margin = annual_revenue - annual_reagent_cost - annual_shipper_cost
            margins[cadence] = annual_margin
            annual_values.update({
                f'runs_per_year_{cadence}': runs_per_year,
                f'tests_per_lab_per_run_{cadence}': int(tests_per_lab_per_run),
                f'annual_revenue_{cadence}_usd': money(annual_revenue),
                f'annual_reagent_cost_{cadence}_usd': money(annual_reagent_cost),
                f'annual_shipper_cost_{cadence}_usd': money(annual_shipper_cost),
                f'annual_margin_{cadence}_usd': money(annual_margin),
            })

        panel_outputs.append({
            'panel_code': panel['panel_code'],
            'panel_name': panel['panel_name'],
            'active_labs': active_labs,
            'base_payment_per_run_per_lab_usd': money(base_payment),
            'network_adjustment_per_run_per_lab_usd': money(network_adjustment),
            'total_payment_per_run_per_lab_usd': money(total_payment),
            'shipper_cost_usd': money(shipper_cost),
            'annual_margin_difference_28_minus_14_usd': money(margins['28_day'] - margins['14_day']),
            **annual_values,
        })

    panel_outputs.sort(key=lambda row: row['panel_code'])

    total_14 = sum(float(row['annual_margin_14_day_usd']) for row in panel_outputs)
    total_28 = sum(float(row['annual_margin_28_day_usd']) for row in panel_outputs)
    total_diff = sum(float(row['annual_margin_difference_28_minus_14_usd']) for row in panel_outputs)
    abs_diff = abs(total_diff)
    decision = 'adopt_28_day' if abs_diff < 6000 else 'keep_14_day'
    if decision == 'adopt_28_day':
        justification = (
            'The absolute total annual margin difference is below the 6000.00 USD '
            'decision threshold, so the 28-day cadence is acceptable.'
        )
    else:
        justification = (
            'The absolute total annual margin difference is at or above the 6000.00 USD '
            'decision threshold, so the 14-day cadence should be retained.'
        )

    report = {
        'metadata': template['metadata'],
        'audit_notes': template['audit_notes'],
        'analysis': {
            'assumptions': {
                'included_analysis_mode': 'review',
                'excluded_holdout_state': 'exclude',
                'runs_per_year_14_day': 26,
                'runs_per_year_28_day': 13,
                'shipper_cost_formula': 'shipper_cost_usd * runs_per_year',
                'shipper_cost_multiplied_by_active_labs': False,
                'decision_threshold_absolute_total_margin_difference_usd': money(6000.0),
            },
            'panels': panel_outputs,
            'totals': {
                'total_annual_margin_14_day_usd': money(total_14),
                'total_annual_margin_28_day_usd': money(total_28),
                'total_annual_margin_difference_28_minus_14_usd': money(total_diff),
                'absolute_total_margin_difference_usd': money(abs_diff),
            },
            'recommendation': {
                'decision': decision,
                'justification': justification,
            },
        },
    }

    with (ROOT / 'diagpanel_policy_report.json').open('w') as f:
        json.dump(report, f, indent=2, cls=FixedCurrencyEncoder)
        f.write('\n')

    summary_lines = [
        f"Total 14-day margin (USD): {total_14:.2f}",
        f"Total 28-day margin (USD): {total_28:.2f}",
        f"Absolute difference (USD): {abs_diff:.2f}",
        f"Final decision: {decision}",
    ]
    with (ROOT / 'diagpanel_policy_summary.md').open('w') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

