            markers = {}
        else:
            markers = None
        if self.ensure_ascii:
            _encoder = encode_basestring_ascii
        else:
            _encoder = encode_basestring

        def floatstr(value, allow_nan=self.allow_nan,
                     _repr=float.__repr__, _inf=math.inf, _neginf=-math.inf):
            if isinstance(value, Currency):
                return format(value, '.2f')
            if value != value:
                text = 'NaN'
            elif value == _inf:
                text = 'Infinity'
            elif value == _neginf:
                text = '-Infinity'
            else:
                return _repr(value)
            if not allow_nan:
                raise ValueError(
                    'Out of range float values are not JSON compliant: ' + repr(value)
                )
            return text

